import {norm,score,review,applyRows,parseCSV,mapSheet,validDate} from './model.mjs';
const paths={trophy:'M8 3h8v5a4 4 0 0 1-8 0V3ZM8 5H4v2a4 4 0 0 0 4 4m8-6h4v2a4 4 0 0 1-4 4M12 12v6m-4 3h8m-7-3h6',target:'M21 12a9 9 0 1 1-9-9m0 5a4 4 0 1 0 4 4M12 12l8-8m-4 0h4v4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-3.87M13 3.13a4 4 0 0 1 0 7.75M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chart:'M4 20V10h4v10M10 20V4h4v16M16 20v-7h4v7',palette:'M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-4 1.5 1.5 0 0 1 1-3h2a4 4 0 0 0 4-4c0-4-4-7-9-7ZM7 9h.01M11 6h.01M16 7h.01M6 14h.01',monitor:'M3 3h18v14H3V3m9 14v4m-4 0h8',arrow:'M5 12h14m-6-6 6 6-6 6',gift:'M3 9h18v4H3V9m2 4v8h14v-8M12 9v12m0-12c-7 0-7-7-3-6 2 0 3 6 3 6Zm0 0c7 0 7-7 3-6-2 0-3 6-3 6Z',clock:'M12 8v4l3 2m6-2a9 9 0 1 1-18 0 9 9 0 0 1 18 0',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-10 4a5 5 0 0 1 6 0m-3 4h.01',upload:'M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8',check:'M5 12l4 4L19 6',crown:'M3 6l4 4 5-7 5 7 4-4-2 13H5L3 6Zm2 16h14',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',edit:'m16 3 5 5-12 12-6 1 1-6L16 3Z',plus:'M12 5v14M5 12h14',lock:'M5 10h14v11H5V10m3 0V6a4 4 0 0 1 8 0v4',info:'M12 11v6m0-10h.01m9 5a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,cls='',disabled=false)=>`<button type="button" class="${cls}" ${action==='help'?'aria-label="Ajuda"':action.startsWith('person:')?'aria-label="Editar vendedor"':''} data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
function seed(){const people=[['ana','Ana Lima','ana.webp',42],['bruno','Bruno Alves','bruno.webp',37],['carla','Carla Souza','carla.webp',35],['diego','Diego Santos','',31],['elisa','Elisa Martins','',28],['felipe','Felipe Rocha','',24]].map(([id,name,photo,count])=>({id,name,photo,count}));const records=people.flatMap(p=>Array.from({length:p.count},(_,i)=>({id:`DEMO-${p.id}-${i+1}`,seller:p.id,date:'2026-10-14',product:'Internet Fibra 500 Mega',status:'ativada',value:'99.90'})));return {people:people.map(({count,...p})=>p),records,campaigns:[{id:'demo',name:'Conexões de outubro',team:'Equipe Fortaleza',members:people.map(p=>p.id),start:'2026-10-01',end:'2026-10-31',event:'ativada',points:1,target:50,collective:250,prize:'Experiência + vale-presente',milestones:true}],selected:'demo',appearance:{color:'#ff781f',name:'Ranking comercial',team:'Equipe Fortaleza',theme:'dark',logo:''},history:[],updated:null}}
let state;try{state=JSON.parse(localStorage.getItem('ranking-commercial-v1'))||seed()}catch{state=seed()}
let page='ranking',tv=false,step=0,draft=null,importStep=0,importRows=[],rawRows=[],fileName='',busy=false;
const current=()=>state.campaigns.find(c=>c.id===state.selected)||state.campaigns[0];
const save=()=>{localStorage.setItem('ranking-commercial-v1',JSON.stringify(state))};
function notify(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function avatar(p){return p.photo?`<img class="avatar" src="${esc(p.photo)}" alt="Foto de ${esc(p.name)}">`:`<span class="avatar">${esc(p.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span>`}
function progress(n,target){return `<div class="progress" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${Math.max(target,n)}" aria-label="Progresso de ${n} de ${target}"><span style="width:${Math.min(100,n/target*100)}%"></span></div>`}
const pct=(n,t)=>Math.round(n/t*100);
function palette(){const a=state.appearance;document.documentElement.style.setProperty('--accent',a.color);const rgb=a.color.match(/\w\w/g).map(x=>parseInt(x,16));document.documentElement.style.setProperty('--accent-rgb',rgb.join(','));const lum=rgb[0]*.299+rgb[1]*.587+rgb[2]*.114;document.documentElement.style.setProperty('--button',lum>145?'#111111':'#ffffff');document.body.classList.toggle('light',a.theme==='light');document.body.classList.toggle('tv',tv)}
function render(){palette();const menus=[['ranking','trophy','Ranking'],['campaigns','target','Campanhas'],['team','users','Equipe'],['results','chart','Resultados'],['appearance','palette','Aparência']];document.querySelector('#app').innerHTML=`<header class="topbar"><div class="brand">${state.appearance.logo?`<img src="${esc(state.appearance.logo)}" alt="Logo" style="max-width:100px;height:32px;object-fit:contain">`:icon('trophy')}${esc(state.appearance.name)} <span class="tag"><span class="dot"></span>Protótipo · dados de demonstração</span></div><div class="topactions">${button(icon('info'),'help','ghost')}${button(icon('monitor')+(tv?'Sair do modo TV':'Modo TV'),'tv','ghost')}</div></header><div class="layout"><aside>${menus.map(([id,ic,label])=>button(icon(ic)+label,'nav:'+id,page===id?'active':'')).join('')}<small>${icon('wifi')}<br>Conquistas que conectam.<br><br>Esta versão salva os dados neste navegador.</small></aside><main>${({ranking:renderRanking,campaigns:renderCampaigns,create:renderCreate,results:renderResults,team:renderTeam,appearance:renderAppearance}[page]||renderRanking)()}</main></div>`;bind()}
function campaignSelect(){return `<select id="campaignSelect" aria-label="Campanha selecionada" style="margin:0;width:230px">${state.campaigns.map(c=>`<option value="${c.id}" ${c.id===state.selected?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`}
function renderRanking(){const c=current();if(!c)return emptyCampaign();const list=score(state.records,c,state.people),total=list.reduce((s,p)=>s+p.total,0);const days=Math.max(0,Math.ceil((new Date(c.end+'T23:59:59-03:00')-new Date())/86400000));return `<div class="pagehead"><div><div class="eyebrow">Cada conexão é uma conquista</div><h1>${esc(c.name)}</h1><p>${esc(c.team)} <span style="margin:0 8px">·</span> ${c.event==='ativada'?'Instalações ativadas':esc(c.event)} valem pontos</p></div><div class="actions">${campaignSelect()}${!tv?button(icon('upload')+'Importar resultados','nav:results','ghost'):''}</div></div><div class="ranking-grid"><section><div class="podium">${[1,0,2].map(i=>{const p=list[i];return p?`<div class="podium-item ${i===0?'first':''}" style="--medal:${['#ffca75','#c7c9d4','#de9b77'][i]}">${i===0?`<div class="crown">${icon('crown')}</div>`:''}${avatar(p)}<span class="rankmedal">${i+1}</span><div class="shield"><h3>${esc(p.name)}</h3><strong>${p.total}</strong><small>${c.points===1?'ativações / pontos':'pontos'}</small><span style="margin-top:15px">${icon('trophy')}</span></div></div>`:''}).join('')}${!list.length?'<div class="empty">Adicione participantes à campanha.</div>':''}</div><div class="panel collective"><div class="collective-head"><div><p>Meta do time</p><strong>${total} <span style="color:var(--muted);font-size:14px;font-weight:400">de ${c.collective} pontos</span></strong></div><strong class="accent">${pct(total,c.collective)}%</strong></div>${progress(total,c.collective)}</div></section><section class="panel"><div class="standing-head"><h2>Classificação</h2><small>Meta individual: ${c.target} pontos</small></div>${list.map((p,i)=>`<div class="standing-row"><span class="position">${i+1}</span>${avatar(p)}<div><h3>${esc(p.name)}</h3><small>${p.total>=c.target?'★ Meta conquistada':`Faltam ${c.target-p.total} pontos para a meta`}</small></div><div class="standing-score"><strong>${p.total}</strong> / ${c.target} <span class="accent">${pct(p.total,c.target)}%</span>${progress(p.total,c.target)}</div></div>`).join('')}</section></div><div class="panel prizebar"><div>${icon('gift')}<div><small>Prêmio da campanha</small><h3>${esc(c.prize||'A definir')}</h3></div></div><div>${icon('clock')}<div><small>${days?'Tempo para conquistar':'Período encerrado'}</small><h3 class="accent">${days?`Faltam ${days} dias`:formatDate(c.end)}</h3></div></div><div>${icon('wifi')}<div><small>Regra da campanha</small><h3>1 ${esc(c.event==='ativada'?'ativação':c.event)} = ${c.points} ponto${c.points>1?'s':''}</h3></div></div></div><div class="footer-note"><span>Empates compartilham a mesma pontuação; a exibição usa ordem alfabética.</span><span>${state.updated?'Atualizado em '+new Date(state.updated).toLocaleString('pt-BR'):'Dados de demonstração · sem integração externa'}</span></div>`}
const formatDate=d=>d.split('-').reverse().join('/');
function emptyCampaign(){return `<div class="empty"><h1>Sua primeira campanha começa aqui</h1><p>Cadastre a equipe e configure metas e prêmios.</p>${button('Criar campanha','create','primary')}</div>`}
function renderCampaigns(){return `<div class="pagehead"><div><div class="eyebrow">Desafios do time</div><h1>Campanhas</h1><p>Defina um objetivo. Acompanhe a jornada. Celebre as conquistas.</p></div>${button(icon('plus')+'Criar campanha','create','primary')}</div><div class="campaign-list">${state.campaigns.map(c=>{const total=score(state.records,c,state.people).reduce((s,p)=>s+p.total,0);return `<article class="panel campaign-card"><div class="hero-preview"><h2>${esc(c.name)}</h2></div><span class="tag">${new Date(c.end+'T23:59:59')<new Date()?'Encerrada':new Date(c.start)>new Date()?'Programada':'Em andamento'}</span><p style="margin-top:13px">${esc(c.team)} · ${c.members.length} participantes</p><p>${formatDate(c.start)} a ${formatDate(c.end)}</p>${progress(total,c.collective)}<div class="meta"><span>${total} de ${c.collective} pontos</span><span>${pct(total,c.collective)}%</span></div>${button('Ver ranking '+icon('arrow'),'select:'+c.id,'primary')}${button('Editar campanha','editCampaign:'+c.id,'ghost')}</article>`}).join('')}</div>`}
function startDraft(c){draft=c?structuredClone(c):{id:'campaign-'+Date.now(),name:'',team:state.appearance.team,members:state.people.map(p=>p.id),start:new Date().toISOString().slice(0,10),end:new Date(Date.now()+30*86400000).toISOString().slice(0,10),event:'ativada',points:1,target:50,collective:250,prize:'',milestones:true};step=0;page='create';render()}
function field(label,name,value,type='text',full=false){return `<label class="${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="1" max="1000000" step="1"':''} required></label>`}
function steps(names,active){return `<div class="steps">${names.map((n,i)=>`<div class="step ${i===active?'active':i<active?'done':''}"><b>${i<active?'✓':i+1}</b>${n}</div>`).join('')}</div>`}
function renderCreate(){return `<div class="pagehead"><div><div class="eyebrow">Uma nova jornada</div><h1>${state.campaigns.some(c=>c.id===draft.id)?'Editar':'Criar'} campanha</h1><p>Transforme a meta do time em um desafio.</p></div>${button('Cancelar','nav:campaigns','ghost')}</div>${steps(['Campanha','Regras','Prêmios','Revisão'],step)}<div class="formgrid"><form id="campaignForm" class="panel"><h2>${['Quem participa do desafio?','Como ganhar pontos','O que o time pode conquistar?','Tudo pronto para começar'][step]}</h2><p>${['Escolha o período e os participantes.','Defina o evento que pontua e as metas.','Apresente o prêmio e os marcos da jornada.','Confira as regras antes de salvar a campanha.'][step]}</p>${step===0?`<div class="fields">${field('Nome da campanha','name',draft.name,'text',true)}${field('Nome do time','team',draft.team,'text',true)}${field('Início','start',draft.start,'date')}${field('Fim','end',draft.end,'date')}</div><h3>Participantes</h3><div class="checklist">${state.people.map(p=>`<label><input type="checkbox" name="members" value="${p.id}" ${draft.members.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div>`:''}${step===1?`<div class="fields"><label class="full">Evento que pontua<select name="event">${[['ativada','Instalação ativada'],['aprovada','Venda aprovada'],['fechada','Venda fechada']].map(([v,l])=>`<option value="${v}" ${draft.event===v?'selected':''}>${l}</option>`).join('')}</select><div class="hint">Somente registros nesse status entram no ranking, dentro do período da campanha.</div></label>${field('Pontos por resultado','points',draft.points,'number')}${field('Meta individual (pontos)','target',draft.target,'number')}${field('Meta coletiva (pontos)','collective',draft.collective,'number',true)}</div><div class="infobox">A contagem usa a <strong>data do evento registrada na planilha</strong>. Cancelamentos deixam de pontuar. Reimportações atualizam a mesma venda pelo ID.</div>`:''}${step===2?`<div class="fields">${field('Prêmio da campanha','prize',draft.prize,'text',true)}</div><div class="checklist"><label><input type="checkbox" name="milestones" ${draft.milestones?'checked':''}>Exibir marcos de conquista na prévia</label></div><div class="infobox">Os prêmios são informativos. A entrega é organizada pelo gestor fora da ferramenta.</div>`:''}${step===3?`<div class="fields"><div><p>Campanha</p><h3>${esc(draft.name)}</h3></div><div><p>Time</p><h3>${esc(draft.team)}</h3></div><div><p>Período</p><h3>${formatDate(draft.start)} a ${formatDate(draft.end)}</h3></div><div><p>Participantes</p><h3>${draft.members.length} vendedores</h3></div><div><p>Pontuação</p><h3>${esc(draft.event)} · ${draft.points} ponto(s)</h3></div><div><p>Meta individual / coletiva</p><h3>${draft.target} / ${draft.collective} pontos</h3></div><div class="full"><p>Prêmio</p><h3>${esc(draft.prize)}</h3></div></div><div class="infobox">${state.campaigns.some(c=>c.id===draft.id)?'Ao salvar, o ranking será recalculado com as novas regras.':'A campanha usará os resultados já importados que corresponderem ao período e aos participantes.'}</div>`:''}<div class="formfooter">${button('Voltar',step?'prev':'nav:campaigns','ghost')}<button type="submit" class="primary">${step===3?'Salvar campanha':'Continuar '+icon('arrow')}</button></div></form><section class="panel"><h2>Prévia da campanha</h2><p>Uma jornada clara para o seu time.</p><div class="hero-preview" style="margin-top:18px"><h2 id="previewName">${esc(draft.name||'Sua próxima conquista')}</h2></div><div class="preview-inner"><p>Sua jornada até a meta</p><div style="display:flex;justify-content:space-between;margin:12px 0"><strong style="font-size:27px" class="accent">0 <span style="color:var(--muted);font-size:18px">/ ${draft.target}</span></strong><span class="tag">${esc(draft.team)}</span></div>${progress(0,draft.target)}</div>${draft.milestones?`<div class="milestones">${[['wifi','Primeiro ponto',1],['target','Metade do caminho',Math.ceil(draft.target/2)],['star','Meta conquistada',draft.target]].map(([ic,l,n])=>`<div><div class="badge">${icon(ic)}</div><h3>${l}</h3><small>${n} ponto(s)</small></div>`).join('')}</div>`:''}<div class="infobox">${icon('gift')}<br><strong>${esc(draft.prize||'Defina uma recompensa para a campanha')}</strong><br>Reconheça o esforço e celebre o resultado.</div></section></div>`}
function captureDraft(form){const d=new FormData(form);for(const [k,v]of d.entries())if(k!=='members')draft[k]=['points','target','collective'].includes(k)?Number(v):v;if(step===0)draft.members=d.getAll('members');if(step===2)draft.milestones=d.has('milestones')}
function renderTeam(){return `<div class="pagehead"><div><div class="eyebrow">Quem faz acontecer</div><h1>Seu time</h1><p>${state.people.length} vendedores · ${esc(state.appearance.team)}</p></div>${button(icon('plus')+'Adicionar vendedor','addPerson','primary')}</div><div class="team-grid">${state.people.map(p=>`<div class="panel person">${avatar(p)}<div><h3>${esc(p.name)}</h3><small>ID: ${esc(p.id)}</small></div>${button(icon('edit'),'person:'+p.id,'ghost')}</div>`).join('')}</div><div class="infobox">Use o <strong>ID ou o nome do vendedor</strong> na planilha. Novos vendedores podem ser incluídos nas campanhas pela edição dos participantes.</div>`}
const sampleCSV=()=>`id_venda;vendedor;data_ativacao;produto;status;valor\nEXEMPLO-001;${state.people[0]?.id||'ana'};${new Date().toISOString().slice(0,10)};Internet Fibra 500 Mega;ativada;99.90\nEXEMPLO-002;${state.people[1]?.id||'bruno'};${new Date().toISOString().slice(0,10)};Internet Fibra 300 Mega;pendente;79.90\n`;
function download(text,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderResults(){const c=current(),errors=importRows.filter(r=>r.errors.length).length;const active=importRows.filter(r=>!r.errors.length&&r.record.status===c?.event&&!r.unchanged).length;return `<div class="pagehead"><div><div class="eyebrow">Resultados que viram conquistas</div><h1>Importar resultados</h1><p>Envie uma planilha e confira os dados antes de atualizar o ranking.</p></div>${campaignSelect()}</div>${steps(['Enviar planilha','Conferir dados','Aplicar resultados'],importStep)}${importStep===0?`<div class="panel"><h2>As conexões do seu time começam aqui</h2><p>Use CSV ou XLSX com uma linha por venda. O modelo contém exemplos fictícios.</p><div class="upload">${icon('upload')}<h2>${busy?'Lendo sua planilha…':'Escolha sua planilha de resultados'}</h2><p>Campos: id_venda, vendedor, data_ativacao, produto, status e valor.</p>${button('Selecionar arquivo','chooseFile','primary',busy)}<input type="file" id="sheetFile" accept=".csv,.xlsx"></div><div class="formfooter">${button(icon('file')+'Baixar modelo CSV','template','ghost')}${button('Experimentar com dados de exemplo','sample','ghost')}</div><div class="infobox">Pontuam somente registros <strong>${esc(c?.event||'ativada')}</strong> no período da campanha. Datas aceitas: AAAA-MM-DD ou DD/MM/AAAA. No XLSX, será usada a primeira aba.</div></div>`:importStep===1?`<div class="panel filebar"><div style="display:flex;gap:13px;align-items:center">${icon('file')}<div><h3>${esc(fileName)}</h3><p>${importRows.length} linhas encontradas · prévia, ainda não aplicada</p></div></div>${button('Trocar arquivo','resetImport','ghost')}</div><div class="stats">${[[active,'Resultados prontos para pontuar'],[importRows.filter(r=>r.kind==='update').length,'Registros existentes'],[importRows.filter(r=>r.record.status==='pendente').length,'Pendentes · não pontuam'],[errors,'Linhas com erro']].map(([n,l])=>`<div class="panel stat"><strong>${n}</strong><small>${l}</small></div>`).join('')}</div><div class="formgrid" style="grid-template-columns:1fr .4fr"><section class="panel"><h2>Conferência da planilha</h2><p>Revise as linhas; IDs existentes serão atualizados, sem duplicação.</p><div class="tablewrap" style="margin-top:20px"><table><thead><tr><th>ID da venda</th><th>Vendedor</th><th>Data</th><th>Status</th><th>Ação</th></tr></thead><tbody>${importRows.slice(0,200).map((r,i)=>`<tr><td>${esc(r.record.id||'Sem ID')}</td><td>${esc(state.people.find(p=>p.id===r.record.seller)?.name||r.record.seller)}</td><td>${esc(r.record.date)}</td><td><span class="status ${r.errors.length?'error':r.record.status==='ativada'?'good':'warn'}">${esc(r.record.status)}</span></td><td>${r.errors.length?`${button(icon('edit')+'Corrigir','fix:'+i,'ghost')}<p style="color:#f18d8d;font-size:10px">${r.errors.map(esc).join('; ')}</p>`:r.unchanged?'Sem alteração':r.kind==='update'?'Atualizar':r.record.status===c?.event?'Adicionar resultado':'Registrar sem pontuar'}</td></tr>`).join('')}</tbody></table>${importRows.length>200?'<p>Prévia limitada a 200 linhas. Todas as linhas serão validadas e aplicadas.</p>':''}</div></section><section class="panel"><div class="accent">${icon('trophy')}</div><h2 style="margin-top:15px">${active} resultados prontos para o desafio</h2><p>O ranking será recalculado após a aplicação.</p><div class="checklist"><p>✓ Somente o status da campanha pontua.</p><p>✓ Registros repetidos não somam novamente.</p><p>✓ Cancelamentos retiram a venda da contagem.</p></div>${errors?`<div class="infobox">${errors} linha(s) precisam de correção.</div>`:''}<div style="margin-top:25px">${button('Aplicar resultados '+icon('arrow'),'apply','primary',!!errors||!importRows.length)}</div></section></div>`:`<div class="panel empty"><div class="accent">${icon('check')}</div><h1>Resultados aplicados!</h1><p>A classificação foi recalculada. Hora de acompanhar as conquistas.</p><div class="actions" style="justify-content:center;margin-top:25px">${button('Ver ranking','nav:ranking','primary')}${button('Importar outra planilha','resetImport','ghost')}</div></div>`}${state.history.length?`<section class="panel" style="margin-top:25px"><h2>Histórico de importações</h2><div class="tablewrap"><table><thead><tr><th>Arquivo</th><th>Data</th><th>Registros</th></tr></thead><tbody>${state.history.slice().reverse().slice(0,8).map(h=>`<tr><td>${esc(h.file)}</td><td>${new Date(h.at).toLocaleString('pt-BR')}</td><td>${h.count}</td></tr>`).join('')}</tbody></table></div></section>`:''}`}
function renderAppearance(){return `<div class="pagehead"><div><div class="eyebrow">O jeito do seu time</div><h1>Aparência</h1><p>Uma identidade própria para cada conquista.</p></div></div><div class="formgrid"><form class="panel" id="appearanceForm"><h2>Identidade visual</h2><div class="fields">${field('Nome da ferramenta','name',state.appearance.name,'text',true)}${field('Nome do time padrão','team',state.appearance.team,'text',true)}<label class="full">Cor principal<div class="swatches">${['#ff781f','#e94d65','#8d71e8','#348bea','#299c79'].map(c=>`<button type="button" class="swatch ${c===state.appearance.color?'selected':''}" style="background:${c}" data-action="color:${c}" aria-label="Usar cor ${c}"></button>`).join('')}</div><input type="color" name="color" id="customColor" value="${state.appearance.color}"><div class="hint">O laranja é o padrão. Você pode escolher qualquer tonalidade.</div></label><label>Tema<select name="theme"><option value="dark" ${state.appearance.theme==='dark'?'selected':''}>Escuro</option><option value="light" ${state.appearance.theme==='light'?'selected':''}>Claro</option></select></label><label>Logo da equipe<input type="file" id="logoFile" accept="image/png,image/jpeg,image/webp"><span class="hint">PNG, JPG ou WebP · até 1 MB</span></label></div><div class="formfooter">${button('Restaurar laranja','color:#ff781f','ghost')}<button type="submit" class="primary">Salvar aparência</button></div>${state.appearance.logo?button('Remover logo','removeLogo','ghost'):''}</form><section class="panel"><h2>Sua identidade em ação</h2><p>A cor escolhida aparece nos destaques, botões e progresso.</p><div class="preview-inner" style="padding:30px;margin-top:25px"><div class="accent" style="margin-bottom:20px">${icon('trophy')}</div><h2>Uma conquista de cada vez</h2><p>Conectando pessoas. Celebrando o time.</p><div style="margin:30px 0">${progress(42,50)}<p>42 de 50 pontos · 84% da meta</p></div>${button('Conquista desbloqueada '+icon('star'),'celebrate','primary')}</div><div class="infobox">Esta personalização é salva neste navegador. A colaboração entre gestores e dispositivos será uma etapa posterior.</div></section></div>`}
function modal(title,content,onSubmit){const wrap=document.createElement('div');wrap.className='dialog-backdrop';wrap.innerHTML=`<form class="panel dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-head"><h2>${esc(title)}</h2><button type="button" class="ghost" aria-label="Fechar">×</button></div>${content}<div class="formfooter"><button type="button" class="ghost" data-close>Cancelar</button><button class="primary" type="submit">Salvar</button></div></form>`;document.body.append(wrap);const previous=document.activeElement;const close=()=>{wrap.remove();previous?.focus()};wrap.querySelector('.dialog-head button').onclick=close;wrap.querySelector('[data-close]').onclick=close;wrap.addEventListener('click',e=>{if(e.target===wrap)close()});wrap.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const f=[...wrap.querySelectorAll('button,input,select')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});wrap.querySelector('form').onsubmit=e=>{e.preventDefault();if(onSubmit(new FormData(e.target))!==false)close()};wrap.querySelector('input,select,button').focus()}
function editPerson(id){const p=state.people.find(x=>x.id===id);modal(p?'Editar vendedor':'Adicionar vendedor',`<div class="fields">${field('Nome completo','name',p?.name||'')}${p?`<p>ID: ${esc(p.id)} · preservado para manter o histórico.</p>`:field('ID do vendedor (único)','id','')}<label>Foto<input type="file" name="photo" accept="image/png,image/jpeg,image/webp"><span class="hint">Opcional · até 1 MB</span></label></div>`,d=>{const name=String(d.get('name')).trim();const pid=p?.id||String(d.get('id')).trim();if(!name||!pid||(!p&&state.people.some(x=>norm(x.id)===norm(pid)))){notify('Informe nome e ID únicos.');return false}if(state.people.some(x=>x.id!==pid&&norm(x.name)===norm(name))){notify('Esse nome já existe. Use um nome que diferencie o vendedor.');return false}const f=d.get('photo');if(f?.size>1024*1024){notify('A foto deve ter no máximo 1 MB.');return false}const person=p||{id:pid,name,photo:''};person.name=name;if(!p)state.people.push(person);if(f?.size){const reader=new FileReader();reader.onload=()=>{person.photo=reader.result;save();render()};reader.readAsDataURL(f)}save();render();notify('Vendedor salvo.');})}
function fixRow(i){const r=rawRows[i];modal('Corrigir resultado',`<div class="fields">${field('ID da venda','id',r.id)}<label>Vendedor<select name="seller">${state.people.map(p=>`<option value="${p.id}" ${p.id===r.seller||norm(p.name)===norm(r.seller)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${field('Data do evento','date',validDate(r.date)?r.date:'','date')}<label>Status<select name="status">${['ativada','pendente','cancelada','aprovada','fechada'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label>${field('Produto','product',r.product)}</div>`,d=>{rawRows[i]={...r,...Object.fromEntries(d)};importRows=review(rawRows,state);render();notify('Linha atualizada na prévia.')})}
async function xlsxRows(buffer){const bytes=new Uint8Array(buffer),dv=new DataView(buffer);let eocd=bytes.length-22;for(;eocd>=Math.max(0,bytes.length-65557);eocd--)if(dv.getUint32(eocd,true)===0x06054b50)break;if(eocd<0)throw Error('Arquivo XLSX inválido');let pos=dv.getUint32(eocd+16,true),count=dv.getUint16(eocd+10,true);const files=new Map(),decoder=new TextDecoder();for(let i=0;i<count;i++){if(dv.getUint32(pos,true)!==0x02014b50)throw Error('Estrutura XLSX inválida');const method=dv.getUint16(pos+10,true),size=dv.getUint32(pos+20,true),uncompressed=dv.getUint32(pos+24,true),nl=dv.getUint16(pos+28,true),el=dv.getUint16(pos+30,true),cl=dv.getUint16(pos+32,true),off=dv.getUint32(pos+42,true);if(uncompressed>20*1024*1024)throw Error('Planilha muito grande');const name=decoder.decode(bytes.slice(pos+46,pos+46+nl));files.set(name,{method,size,off});pos+=46+nl+el+cl}async function xml(name){const f=files.get(name);if(!f)return null;let start=f.off+30+dv.getUint16(f.off+26,true)+dv.getUint16(f.off+28,true),data=bytes.slice(start,start+f.size);if(f.method===8){try{data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}catch{throw Error('Não foi possível abrir este XLSX neste navegador. Salve a planilha como CSV e importe novamente.')}}else if(f.method!==0)throw Error('Compressão XLSX não suportada');const dom=new DOMParser().parseFromString(decoder.decode(data),'application/xml');if(dom.querySelector('parsererror'))throw Error('Conteúdo XLSX inválido');return dom}const shared=await xml('xl/sharedStrings.xml'),strings=shared?[...shared.getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(x=>x.textContent).join('')):[];const book=await xml('xl/workbook.xml'),rels=await xml('xl/_rels/workbook.xml.rels');const first=book?.getElementsByTagName('sheet')[0],rid=first?.getAttribute('r:id');let rel=rels?[...rels.getElementsByTagName('Relationship')].find(x=>x.getAttribute('Id')===rid):null;const target=rel?.getAttribute('Target')||'worksheets/sheet1.xml';const path=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');const sheet=await xml(path);if(!sheet)throw Error('A primeira aba não foi encontrada');return [...sheet.getElementsByTagName('row')].map(row=>{const cells=[];for(const c of row.getElementsByTagName('c')){const letters=(c.getAttribute('r')||'A').match(/[A-Z]+/)[0];let idx=0;for(const x of letters)idx=idx*26+x.charCodeAt(0)-64;const type=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent||'';cells[idx-1]=type==='s'?strings[Number(v)]||'':type==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):v}return cells})}
async function loadFile(file){if(!file)return;if(file.size>5*1024*1024){notify('Use uma planilha de até 5 MB.');return}busy=true;render();try{let rows;if(/\.xlsx$/i.test(file.name))rows=await xlsxRows(await file.arrayBuffer());else if(/\.csv$/i.test(file.name))rows=parseCSV(await file.text());else throw Error('Escolha um arquivo CSV ou XLSX.');rawRows=mapSheet(rows);if(!rawRows.length)throw Error('A planilha não tem resultados');if(rawRows.length>10000)throw Error('Importe até 10.000 linhas por vez');fileName=file.name;importRows=review(rawRows,state);importStep=1}catch(e){notify(e.message)}finally{busy=false;render()}}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelector('#campaignSelect')?.addEventListener('change',e=>{state.selected=e.target.value;save();render()});document.querySelector('#campaignForm')?.addEventListener('submit',e=>{e.preventDefault();captureDraft(e.target);if(step===0&&(!draft.name.trim()||!draft.team.trim()||!draft.members.length||draft.start>draft.end)){notify('Informe nome, time, participantes e um período válido.');return}if(step===1&&['points','target','collective'].some(k=>!Number.isInteger(draft[k])||draft[k]<1)){notify('Use valores inteiros positivos.');return}if(step<3){step++;render()}else{const i=state.campaigns.findIndex(c=>c.id===draft.id);if(i<0)state.campaigns.push(draft);else state.campaigns[i]=draft;state.selected=draft.id;save();page='ranking';render();notify('Campanha salva!')}});document.querySelector('#campaignForm input[name=name]')?.addEventListener('input',e=>{document.querySelector('#previewName').textContent=e.target.value||'Sua próxima conquista'});document.querySelector('#sheetFile')?.addEventListener('change',e=>loadFile(e.target.files[0]));document.querySelector('#appearanceForm')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.appearance={...state.appearance,...Object.fromEntries(d)};save();render();notify('Aparência salva.')});document.querySelector('#customColor')?.addEventListener('input',e=>{state.appearance.color=e.target.value;palette()});document.querySelector('#logoFile')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024){notify('Use uma imagem de até 1 MB.');return}const rd=new FileReader();rd.onload=()=>{state.appearance.logo=rd.result;save();render();notify('Logo atualizado.')};rd.readAsDataURL(f)})}
function action(a){const [cmd,...rest]=a.split(':'),arg=rest.join(':');if(cmd==='nav'){page=arg;tv=false;render()}else if(cmd==='tv'){tv=!tv;if(tv)page='ranking';render()}else if(cmd==='create')startDraft();else if(cmd==='editCampaign')startDraft(state.campaigns.find(c=>c.id===arg));else if(cmd==='select'){state.selected=arg;page='ranking';save();render()}else if(cmd==='prev'){captureDraft(document.querySelector('#campaignForm'));step--;render()}else if(cmd==='addPerson')editPerson();else if(cmd==='person')editPerson(arg);else if(cmd==='template')download(sampleCSV(),'modelo_ativacoes.csv');else if(cmd==='chooseFile')document.querySelector('#sheetFile').click();else if(cmd==='resetImport'){importStep=0;rawRows=[];importRows=[];render()}else if(cmd==='sample'){rawRows=mapSheet(parseCSV(sampleCSV()));fileName='exemplo_ativacoes.csv';importRows=review(rawRows,state);importStep=1;render()}else if(cmd==='fix')fixRow(Number(arg));else if(cmd==='apply'){try{const latest=review(rawRows,state);state.records=applyRows(state.records,latest);state.updated=new Date().toISOString();state.history.push({file:fileName,at:state.updated,count:latest.length});save();importStep=2;render();notify('Resultados aplicados sem duplicação.')}catch(e){notify(e.message)}}else if(cmd==='color'){const f=document.querySelector('#appearanceForm');if(f){state.appearance.name=f.elements.name.value;state.appearance.team=f.elements.team.value;state.appearance.theme=f.elements.theme.value}state.appearance.color=arg;render()}else if(cmd==='removeLogo'){state.appearance.logo='';save();render()}else if(cmd==='celebrate')notify('★ Meta conquistada! Cada conexão faz a diferença.');else if(cmd==='help')modal('Como usar o ranking',`<div class="checklist"><p><strong>1. Equipe:</strong> cadastre seus vendedores.</p><p><strong>2. Campanhas:</strong> defina período, participantes, pontos, metas e prêmio.</p><p><strong>3. Resultados:</strong> importe CSV ou XLSX e confira antes de aplicar.</p><p><strong>4. Ranking:</strong> acompanhe a classificação e use o modo TV.</p><p><strong>5. Aparência:</strong> personalize cores e logo.</p></div><div class="infobox">Este é um protótipo com dados fictícios. Os dados ficam neste navegador, sem sincronização entre dispositivos. As fotos são ilustrativas. O encerramento formal e a confirmação dos vencedores serão implementados na etapa de uso real.</div>`,()=>true)}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&tv){tv=false;render()}});
render();
